"""Upgrade the offline preview's information hierarchy without simulating research results."""
import re,json


def upgrade(html):
    html=html.replace('V28 AUTO','V29 STRATEGY LAB').replace('開啟，就從推薦開始。','選股決策中心')
    html=html.replace('<div class="eyebrow">INVESTMENT DESK</div><h1>選股決策中心</h1><div class="sub">選一個操作週期，先看入選原因，再決定是否加入投資觀察。</div>', '<div class="preview-hero"><div class="eyebrow">01 / INVESTMENT DESK</div><h1>選股決策中心</h1><div class="sub">先看完整名單與策略證據，再查個股、進出價格與資金配置。</div></div>')
    html=html.replace('<span class="status">真實快照</span>','<span class="status">初選・未驗效</span>')
    html=html.replace('<div class="cards" id="cards"></div>','<div class="preview-metrics" id="screenMetrics"></div><div class="panel scroll" id="decisionTable"></div><details open><summary>三檔重點與投資參考</summary><div class="cards" id="cards"></div></details>')
    html=html.replace('</head>','''<style>
.preview-hero{background:linear-gradient(115deg,#142e48,#1a4a58);padding:26px 30px;border-radius:16px;color:white}.preview-hero .eyebrow{color:#83d1c4;margin-top:0}.preview-hero h1{font-size:31px}.preview-hero .sub{color:#c6d8e2}.preview-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:20px 0}.preview-metric{background:white;border:1px solid var(--line);border-top:3px solid #138f87;border-radius:10px;padding:15px 18px}.preview-metric span{font-size:10px;color:var(--muted);display:block}.preview-metric b{display:block;font-size:20px;margin-top:5px}.preview-metric small{display:block;font-size:10px;color:var(--muted);margin-top:3px}#decisionTable{padding:0}#decisionTable td:first-child,#decisionTable th:first-child{position:sticky;left:0;background:white;z-index:1;box-shadow:1px 0 0 var(--line)}#decisionTable th:first-child{background:#f7f9fb}#decisionTable tr:hover td{background:#f1f8f7}#decisionTable td{padding:13px 15px}#decisionTable td:nth-child(8){white-space:normal;min-width:280px;line-height:1.8}.lab-panel .panel{box-shadow:0 7px 25px #15394b05}
@media(max-width:760px){.preview-hero{padding:22px}.preview-hero h1{font-size:27px}.preview-metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.preview-metric{padding:12px}.preview-metric b{font-size:17px}.preview-metric small{font-size:9px}#labTabs{width:100%}#labTabs button{padding:8px 10px;flex:1}}
</style></head>''')
    research='''<section id="research" class="hidden"><div class="eyebrow">STRATEGY RESEARCH</div><h1>策略驗效與優化中心</h1><div class="sub">完整保留因子、權重、試驗與績效證據；以樣本外淨報酬作研究目標。</div>
<div class="segments" id="labTabs" style="margin-top:25px;flex-wrap:wrap"><button class="active" data-lab="summary">驗效總覽</button><button data-lab="factors">因子研究</button><button data-lab="race">策略競賽</button><button data-lab="report">研究報告</button></div>
<div class="lab-panel" data-lab-panel="summary"><div class="conclusion"><small>目前投資驗效狀態</small><h2>尚無本版投資績效結果</h2><p>資料檢核與程式測試已完成，不代表報酬、回撤或勝率已驗證。</p></div><div class="research-cells"><div class="research-cell"><span>完成歷史試驗</span><b>0次，等待研究資料</b></div><div class="research-cell"><span>正式採用策略</span><b>0／3週期</b></div><div class="research-cell"><span>快照用途</span><b>初選觀察，非驗效證據</b></div></div><div class="panel scroll"><table><tr><th>週期</th><th>保留期年化</th><th>同期0050</th><th>最大回撤</th><th>結論</th></tr><tr><td>短線</td><td>待測</td><td>待測</td><td>待測</td><td>未驗效</td></tr><tr><td>中線</td><td>待測</td><td>待測</td><td>待測</td><td>未驗效</td></tr><tr><td>長線</td><td>待測</td><td>待測</td><td>待測</td><td>未驗效</td></tr></table></div><div class="panel"><h2>持續研究流程</h2><p>背景補齊歷史 → 因子IC／ICIR → 分批候選競賽 → 成本與回撤門檻 → 鎖定冠軍 → 保留期一次檢查。</p><p class="fine">正式程式可啟用持續研究、暫停及續跑；HTML離線預覽不執行背景回測。</p></div></div>
<div class="lab-panel hidden" data-lab-panel="factors"><div class="panel"><h2>完整因子研究</h2><p>研究引擎恢復精簡因子選擇、IC權重估計、成長／動能融合與續抱門檻競賽，短中長線各自驗證。</p><p class="fine">以下為首頁快照的固定先驗，尚未證實是最佳權重。歷史資料就緒後，正式程式提供IC／ICIR、涵蓋率、逐期權重與候選比較。</p><div id="modelInfo"></div></div></div>
<div class="lab-panel hidden" data-lab-panel="race"><div class="panel"><h2>策略競賽與版本紀錄</h2><p>比較成交金額／市值／混合母池、3／5／6／8因子、不同融合比例、續抱緩衝、現金或0050餘款。</p><p>先依成本後報酬、最大回撤45%、區段勝率50%及額外來回0.5%成本條件篩選；再評估鎖定冠軍的保留期。</p><button class="btn" disabled>開始／接續策略競賽（請使用程式版）</button><div class="empty">尚無本版已完成試驗，排行榜保持空白。每次試驗均保留，不只展示最高一次。</div><p class="fine">已檢視的保留期鎖定；正式策略還需PIT、歷史名冊、企業行動與多重試驗校正通過。</p></div></div>
<div class="lab-panel hidden" data-lab-panel="report"><div class="panel"><h2>研究報告與可核對數據</h2><p>區分資料檢核、程式測試與投資績效。完整結果由程式版產生。</p><button class="btn primary" id="downloadReport">下載驗效與優化研究報告</button><button class="btn" id="downloadResearch">下載研究數據 JSON</button><p class="toast" id="reportToast"></p></div></div></section>'''
    html=re.sub(r'<section id="research".*?</section>',lambda _:research,html,flags=re.S)
    script='''<script>
const copyDecision=()=>{const list=D.selections[horizon],target=document.getElementById('decisionTable');if(!target)return;
target.innerHTML=table(['股票／族群','模型狀態','相對分數','因子涵蓋','參考價','買進參考區','防守參考','入選助力'],list.map(t=>{const s=D.stocks[t],r=s.scores[horizon],p=s.plans[horizon];return [`<b>${esc(t+' '+s.name)}</b><br><small class="fine">${esc(s.group)}</small>`,'初選・未驗效',num(r.score,1),num(r.coverage*100,0)+'%',px(s.price),p.buy_low==null?'待K線確認':px(p.buy_low)+'–'+px(p.buy_high),p.alert==null?'待確認':px(p.alert),esc(r.reasons)]}),list);
const coverage=list.length?list.reduce((sum,t)=>sum+(D.stocks[t].scores[horizon].coverage||0),0)/list.length:0;
document.getElementById('screenMetrics').innerHTML=[['本週期候選',list.length+' 檔','點選總表查看個股'],['平均因子涵蓋',num(coverage*100,0)+'%','資料缺漏會揭露'],['策略狀態','初選・未驗效','分數不是投資勝率'],['研究進度','等待歷史資料','驗效專區可持續研究']].map(([a,b,c])=>`<div class="preview-metric"><span>${a}</span><b>${b}</b><small>${c}</small></div>`).join('');};copyDecision();
new MutationObserver(copyDecision).observe(document.getElementById('candidateTable'),{childList:true,subtree:true});
document.getElementById('labTabs').onclick=e=>{const b=e.target.closest('[data-lab]');if(!b)return;document.querySelectorAll('[data-lab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-lab-panel]').forEach(x=>x.classList.toggle('hidden',x.dataset.labPanel!==b.dataset.lab));};
document.getElementById('downloadResearch').onclick=()=>download('AlphaRadar_V29_Trials.json',JSON.stringify(D.lab,null,2),'application/json');
document.getElementById('downloadReport').onclick=()=>{download('AlphaRadar_V29_Validation_Report.html',D.report_html,'text/html;charset=utf-8');document.getElementById('reportToast').innerText='已產生驗效報告；沒有歷史試驗的欄位保持待測。';};
</script>'''
    return html.replace('</body>',script+'</body>')
